export interface DemoBusinessInput {
  businessName: string;
  location: string;
  industry: string;
  services?: readonly string[];
  website?: string | null;
  contactEmail?: string | null;
  phone?: string | null;
  description?: string;
  templateId?: DemoTemplateId;
  fixture?: boolean;
  /** Sourced business facts and inert, downloaded raster images. Never customer HTML. */
  businessProfile?: BusinessProfile;
  /** Owner-selected studio identity. It never changes the prospect's business facts. */
  studio?: { name: string; website?: string };
}

export interface RenderedDemoWebsite {
  readonly html: string;
  readonly templateId: DemoTemplateId;
  readonly templateName: string;
  readonly template: DemoTemplate;
  readonly attribution: string;
  readonly contentHash: string;
  readonly contentSecurityPolicy: string;
  readonly fixture: boolean;
  readonly externalAssets: readonly string[];
  readonly designBrief?: Readonly<ImmersiveDesignBrief>;
}

interface PreparedBusiness {
  businessName: string; location: string; industry: string; services: string[];
  website: string | null; contactEmail: string | null; phone: string | null; description: string; fixture: boolean;
  address: string; profileSource: string | null; profileDetail: string; logo: BusinessImage | null; images: BusinessImage[];
  studioName: string; studioWebsite: string | null;
}

const text = (value: unknown, field: string, max: number, required = true): string => {
  if (typeof value !== "string") {
    if (!required && (value === null || value === undefined)) return "";
    throw new Error(`${field} must be plain text.`);
  }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value)) throw new Error(`${field} contains unsupported control characters.`);
  const result = value.replace(/\s+/g, " ").trim();
  if ((required && !result) || result.length > max) throw new Error(`${field} must contain ${required ? "1" : "0"}–${max} characters.`);
  return result;
};

/** Escape content at every HTML text/attribute boundary; no customer HTML is accepted. */
export const escapeDemoHtml = (value: string): string => value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!);
const e = escapeDemoHtml;

/** This only validates an inert link; it never fetches or resolves a customer-controlled URL. */
export function safeDemoWebsite(raw: string | null | undefined): string | null {
  if (raw === null || raw === undefined || raw === "") return null;
  if (typeof raw !== "string" || raw.length > 2048 || /[\u0000-\u0020\u007f\\]/.test(raw)) throw new Error("Website must be a public HTTPS URL without credentials.");
  let url: URL;
  try { url = new URL(raw); } catch { throw new Error("Website must be a public HTTPS URL without credentials."); }
  const host = url.hostname.replace(/^\[|\]$/g, "").replace(/\.$/, "").toLowerCase();
  if (url.protocol !== "https:" || url.username || url.password || (url.port && url.port !== "443") || !host ||
    (!isIP(host) && (!host.includes(".") || /(?:^|\.)(localhost|local|internal|home|lan|test|invalid|example)$/.test(host) || !/^[a-z0-9.-]+$/.test(host))) ||
    (isIP(host) && !isPublicAddress(host))) throw new Error("Website must be a public HTTPS URL without credentials.");
  url.search = "";
  url.hash = "";
  return url.href;
}

const optionalProfileText = (raw: unknown, max: number): string => {
  if (typeof raw !== "string") return "";
  return raw.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
};

/** Defence in depth: even an imported profile cannot cause a remote image request or render an SVG. */
function safeBusinessImage(raw: unknown): BusinessImage | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const image = raw as Partial<BusinessImage>;
  if (typeof image.dataUrl !== "string" || image.dataUrl.length > 2_800_000 ||
      typeof image.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(image.sha256) ||
      !Number.isInteger(image.width) || !Number.isInteger(image.height) || image.width! < 1 || image.height! < 1 ||
      image.width! > 12_000 || image.height! > 12_000 || image.width! * image.height! > 40_000_000) return null;
  const match = /^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/]+={0,2})$/.exec(image.dataUrl);
  if (!match || image.mime !== match[1] || match[2]!.length % 4 !== 0) return null;
  const bytes = Buffer.from(match[2]!, "base64");
  if (bytes.length > 2_000_000 || bytes.toString("base64") !== match[2] || createHash("sha256").update(bytes).digest("hex") !== image.sha256) return null;
  const isRaster = image.mime === "image/png" ? bytes.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10]))
    : image.mime === "image/jpeg" ? bytes.length > 3 && bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255
    : bytes.length >= 12 && bytes.subarray(0, 4).toString("ascii") === "RIFF" && bytes.subarray(8, 12).toString("ascii") === "WEBP";
  if (!isRaster) return null;
  let sourceUrl: string | null = null;
  try { sourceUrl = safeDemoWebsite(image.sourceUrl); } catch { /* Invalid source evidence is omitted with the asset. */ }
  if (!sourceUrl) return null;
  return { dataUrl: image.dataUrl, sourceUrl, alt: optionalProfileText(image.alt, 180) || "Business image from its existing website", mime: image.mime!, sha256: image.sha256, width: image.width!, height: image.height! };
}

function prepare(input: DemoBusinessInput): PreparedBusiness {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("A structured business record is required.");
  if (input.services !== undefined && (!Array.isArray(input.services) || input.services.length > 8)) throw new Error("Provide at most eight verified service names.");
  const profile = input.businessProfile && typeof input.businessProfile === "object" && !Array.isArray(input.businessProfile) ? input.businessProfile : undefined;
  const sourceServices = input.services?.length ? input.services : (Array.isArray(profile?.services) ? profile.services.slice(0, 8).map(service => optionalProfileText(service, 100)).filter(Boolean) : []);
  const services = [...new Map(sourceServices.map((service) => {
    const name = text(service, "Service name", 100);
    return [name.toLocaleLowerCase("en-AU"), name] as const;
  })).values()];
  const contactEmail = text(input.contactEmail, "Contact email", 254, false) || null;
  if (contactEmail && !/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,63}$/i.test(contactEmail)) throw new Error("Contact email is invalid.");
  let profilePhone = optionalProfileText(profile?.phone, 32);
  if (profilePhone && (!/^\+?[\d() .-]{6,32}$/.test(profilePhone) || profilePhone.replace(/\D/g, "").length < 6 || profilePhone.replace(/\D/g, "").length > 15)) profilePhone = "";
  const phone = text(input.phone, "Phone", 32, false) || profilePhone || null;
  if (phone && (!/^\+?[\d() .-]{6,32}$/.test(phone) || phone.replace(/\D/g, "").length < 6 || phone.replace(/\D/g, "").length > 15)) throw new Error("Phone must be a factual telephone number.");
  if (input.fixture !== undefined && typeof input.fixture !== "boolean") throw new Error("Fixture flag must be true or false.");
  let profileSource: string | null = null;
  try { profileSource = safeDemoWebsite(profile?.sourceUrl); } catch { /* An unavailable source stays explicitly unverified. */ }
  const images = Array.isArray(profile?.images) ? profile.images.slice(0, 3).map(safeBusinessImage).filter((image): image is BusinessImage => image !== null) : [];
  return { businessName: text(input.businessName, "Business name", 160), location: text(input.location, "Location", 160), industry: text(input.industry, "Industry", 120), services,
    website: safeDemoWebsite(input.website), contactEmail, phone, description: text(input.description, "Description", 900, false) || optionalProfileText(profile?.description, 900), fixture: input.fixture === true,
    address: optionalProfileText(profile?.address, 320), profileSource, profileDetail: optionalProfileText(profile?.detail, 500), logo: safeBusinessImage(profile?.logo), images,
    studioName: input.studio === undefined ? "Wulff Studio" : text(input.studio.name, "Studio name", 160), studioWebsite: safeDemoWebsite(input.studio?.website) };
}

