function nav(b: PreparedBusiness): string {
  const branding = b.logo ? `<span class="business-logo-frame">${businessImage(b.logo, "business-logo", false, `${b.businessName} logo from its existing website`)}</span>` : mark;
  return `<header class="site-nav"><a href="#main" class="brand" aria-label="${e(b.businessName)} concept home">${branding}<span class="brand-name">${e(b.businessName)}</span></a><nav class="nav-links" aria-label="Concept navigation"><a href="#services">Services</a><a href="#direction">The direction</a></nav><div class="nav-end"><a class="nav-button" href="#concept">About this concept ${arrow}</a></div></header>`;
}

function businessImage(image: BusinessImage, className: string, lazy = false, alt = image.alt): string {
  return `<img class="${className}" src="${image.dataUrl}" width="${image.width}" height="${image.height}" alt="${e(alt)}" decoding="async"${lazy ? ' loading="lazy"' : ""}>`;
}

function heroImage(b: PreparedBusiness, fallback: () => string): string {
  return b.images[0] ? businessImage(b.images[0], "business-hero-image") : fallback();
}

function imageCredit(b: PreparedBusiness): string {
  return b.images[0] ? `<a href="${e(b.images[0].sourceUrl)}" target="_blank" rel="noopener noreferrer">Image from the business’s existing website</a>` : `Original illustration / ${e(b.studioName)}`;
}

function locationLine(b: PreparedBusiness): string {
  if (!b.address && !b.phone) return "";
  return `<div class="business-location-line"><svg width="14" height="18" viewBox="0 0 14 18" fill="none" aria-hidden="true"><path d="M12 6.5C12 11 7 16 7 16S2 11 2 6.5a5 5 0 1 1 10 0Z" stroke="currentColor"/><circle cx="7" cy="6.5" r="1.5" stroke="currentColor"/></svg><span>${b.address ? e(b.address) : e(b.location)}${b.phone ? `<br>${e(b.phone)} · display only` : ""}</span></div>`;
}

function businessGallery(b: PreparedBusiness): string {
  const images = b.images.slice(1);
  if (!images.length) return "";
  return `<section class="business-gallery" aria-label="Images from the business website"><div class="eyebrow">A closer look / From the business’s existing website</div><div class="business-gallery-grid">${images.map((image, index) => `<figure>${businessImage(image, "business-gallery-image", true)}<figcaption><span>${e(image.alt)}</span><a href="${e(image.sourceUrl)}" target="_blank" rel="noopener noreferrer">Source ${String(index + 2).padStart(2, "0")} ↗</a></figcaption></figure>`).join("")}</div></section>`;
}

function assetProvenance(b: PreparedBusiness): string {
  const sources = [...(b.logo ? [{ label: "Business logo", image: b.logo }] : []), ...b.images.map((image, index) => ({ label: `Business image ${index + 1}`, image }))];
  if (!b.profileSource && !sources.length) return `<p class="asset-fallback-note">Business logos and photographs have not been verified for this concept. The illustration is original ${e(b.studioName)} artwork.</p>`;
  return `<div class="asset-provenance"><p>${sources.length ? "Business branding and photographs are sourced from the business’s existing website for this independent design review. Their inclusion does not establish ownership, permission or endorsement; usage rights and business details need confirmation before launch." : `The business’s existing website was checked, but no suitable business logo or photograph was available for this concept. The illustration is original ${e(b.studioName)} artwork.`}</p>${b.profileSource ? `<p><a href="${e(b.profileSource)}" target="_blank" rel="noopener noreferrer">Business information source ↗</a>${b.address ? " · Street address shown as published by the business; not independently verified." : " · Street address not confirmed; the supplied research location is shown."}</p>` : ""}${sources.length ? `<ul class="image-source-list">${sources.map(({ label, image }) => `<li><a href="${e(image.sourceUrl)}" target="_blank" rel="noopener noreferrer">${label} ↗</a></li>`).join("")}</ul>` : ""}</div>`;
}

function serviceRows(b: PreparedBusiness): string {
  if (!b.services.length) return '<p class="services-pending">Service information has not been verified for this concept. This space is reserved for confirmed details.</p>';
  return `<div class="service-list">${b.services.map((service, i) => `<div class="service-row"><span>${String(i + 1).padStart(2, "0")}</span><h3>${e(service)}</h3>${arrow}</div>`).join("")}</div>`;
}

function designPoints(): string {
  return `<div><div class="design-point"><span>01</span><div><h3>A stronger first impression.</h3><p>A distinct visual direction, shaped around the business rather than a generic landing page.</p></div></div><div class="design-point"><span>02</span><div><h3>The useful details, up front.</h3><p>Space for verified services, location and contact details, with a clearer path through the page.</p></div></div><div class="design-point"><span>03</span><div><h3>Made to feel right on mobile.</h3><p>A responsive design study that keeps the essential information easy to read on smaller screens.</p></div></div></div>`;
}

function lead(b: PreparedBusiness): string {
  return e(b.description || `An independent website concept for ${b.businessName}, exploring a clearer presentation of its business in ${b.location}.`);
}

function fieldworkHeadline(b: PreparedBusiness): string {
  const industry = b.industry.toLocaleLowerCase("en-AU");
  if (/fenc|gate/.test(industry)) return "Boundaries.<br>Built with<br><em>purpose.</em>";
  if (/plumb/.test(industry)) return "A clearer<br>flow.<br><em>By design.</em>";
  if (/electri/.test(industry)) return "A brighter<br>way<br><em>forward.</em>";
  if (/garden|landscap/.test(industry)) return "Room to<br>grow.<br><em>Naturally.</em>";
  if (/auto|tyre|mechanic/.test(industry)) return "Ready for<br>the road<br><em>ahead.</em>";
  return "Local work.<br>A lasting<br><em>impression.</em>";
}

function folioHeadline(b: PreparedBusiness): string {
  const industry = b.industry.toLocaleLowerCase("en-AU");
  if (/detail|automotive/.test(industry)) return "A finer<br>first<br><em>finish.</em>";
  if (/beauty|salon|wellness/.test(industry)) return "A moment<br>for<br><em>yourself.</em>";
  return "Clarity.<br>Care.<br><em>Direction.</em>";
}

function fieldwork(b: PreparedBusiness): string {
  return `<section class="hero field-hero"><div class="hero-text"><div class="eyebrow eyebrow-line">${e(b.industry)} / ${e(b.location)}</div><h1>${fieldworkHeadline(b)}</h1><div class="hero-copy"><p>${lead(b)}</p></div>${locationLine(b)}<a class="cta" href="#services">Explore the concept ${arrow}</a></div><div><div class="field-art${b.images.length ? " has-business-image" : ""}">${heroImage(b, architectureArt)}<div class="field-tag">${tinyPlus}<div><strong>${e(b.businessName)}</strong><span>Independent website concept</span></div></div></div><div class="hero-caption"><span>${imageCredit(b)}</span><span>Design direction 01</span></div></div></section><section id="services" class="service-section"><div class="field-section-kicker"><span>LOCAL BUSINESS. A FRESH PERSPECTIVE.</span><span>DESIGNED WITH PURPOSE.</span></div><div class="section-heading"><div><div class="eyebrow">What the business does</div><h2>Good work deserves<br>a clearer introduction.</h2></div><p>${b.services.length ? "Service names supplied for this concept. Descriptions, images and business claims need confirmation before launch." : "A considered framework for the services the business chooses to present."}</p></div>${serviceRows(b)}</section>${businessGallery(b)}<section id="direction" class="design-section field-design"><div class="wrap design-grid"><div class="field-quote"><div class="quote-shape">${mark}</div><h2>Less noise.<br>More character.</h2><p>A PROPOSED DESIGN DIRECTION<br>FOR ${e(b.businessName.toLocaleUpperCase("en-AU"))}</p></div>${designPoints()}</div></section>`;
}

function momentum(b: PreparedBusiness): string {
  return `<section class="hero momentum-hero"><div class="hero-text"><div class="eyebrow eyebrow-line">${e(b.industry)} / ${e(b.location)}</div><h1>MAKE<br>YOUR<br><em>MOVE.</em></h1><div class="hero-copy"><p>${lead(b)}</p></div>${locationLine(b)}<a class="cta" href="#services">Explore the concept ${arrow}</a></div><div><div class="momentum-art${b.images.length ? " has-business-image" : ""}">${heroImage(b, kineticArt)}<div class="momentum-art-caption"><span>A proposed digital identity for ${e(b.businessName)}</span><strong>GO.</strong></div></div><div class="hero-image-credit">${imageCredit(b)}</div></div></section><div class="momentum-marquee" aria-hidden="true"><span>FORM WITH PURPOSE</span><i>✳</i><span>ROOM TO GROW</span><i>✳</i><span>A NEW DIRECTION</span></div><section id="services" class="service-section momentum-services"><div class="section-heading"><div><div class="eyebrow">What the business does</div><h2>A sharper<br>starting point.</h2></div><p>Presenting the supplied service names with a more confident, more memorable design direction.</p></div>${serviceRows(b)}</section>${businessGallery(b)}<section id="direction" class="design-section momentum-design"><div class="wrap design-grid"><div><div class="eyebrow">The creative direction</div><h2>LESS<br>SCROLL.<br>MORE<br>IMPACT.</h2></div>${designPoints()}</div></section>`;
}

function folio(b: PreparedBusiness): string {
  return `<section class="hero folio-hero"><div class="hero-text"><div class="eyebrow eyebrow-line">${e(b.industry)} / ${e(b.location)}</div><h1>${folioHeadline(b)}</h1><div class="hero-copy"><p>${lead(b)}</p></div>${locationLine(b)}<a class="cta" href="#services">Explore the concept ${arrow}</a></div><div class="folio-art${b.images.length ? " has-business-image" : ""}">${heroImage(b, folioArt)}<div class="art-tag"><span>Balance / Clarity / Direction</span><span>${e(b.studioName)}<br>Original design concept</span></div></div><div class="hero-caption"><span>${b.images.length ? imageCredit(b) : `A considered direction for ${e(b.businessName)}`}</span><span>Independent concept / Not a live business website</span></div></section><section id="services" class="service-section folio-services"><div class="section-heading"><div><div class="eyebrow">What the business does</div><h2>The essentials,<br>thoughtfully presented.</h2></div><p>${b.services.length ? "Supplied service names, given space to be seen. Detailed copy is to be confirmed before any launch." : "A quiet, confident framework ready for confirmed service information."}</p></div>${serviceRows(b)}</section>${businessGallery(b)}<section id="direction" class="design-section folio-design"><div class="wrap design-grid"><div><div class="eyebrow">The creative direction</div><h2>A little clarity.<br>A different<br>perspective.</h2><span class="folio-section-mark" aria-hidden="true">Aa.</span></div>${designPoints()}</div></section>`;
}

function clarity(b: PreparedBusiness): string {
  return `<section class="hero clarity-hero"><div class="hero-text clarity-arrive"><div class="eyebrow">${e(b.industry)} · ${e(b.location)}</div><h1>${e(b.businessName)}<span>A fresh perspective.</span></h1><div class="hero-copy"><p>${lead(b)}</p></div><a class="cta" href="#services">Explore the concept ${arrow}</a>${locationLine(b)}</div><div class="clarity-visual${b.images.length ? " has-business-image" : ""}">${heroImage(b, clarityArt)}<div class="clarity-image-label"><strong>${e(b.businessName)}</strong><span>${b.images.length ? "From the business’s own website" : "Original abstract illustration"}</span></div></div><div class="clarity-caption"><span>${imageCredit(b)}</span><span>Independent concept · Business details to be confirmed</span></div></section><section id="services" class="service-section clarity-services"><div class="section-heading"><div><div class="eyebrow">The essentials, thoughtfully presented.</div><h2>Good work.<br>A clearer introduction.</h2></div><p>${b.services.length ? "Service names from the recorded research. Descriptions and business claims need confirmation before launch." : "A focused framework, ready for the business’s confirmed services and details."}</p></div>${serviceRows(b)}</section>${businessGallery(b)}<section id="direction" class="design-section clarity-direction"><div class="wrap design-grid"><div><div class="eyebrow">The creative direction</div><h2>More room<br>for what<br><span>matters.</span></h2><p class="clarity-direction-copy">Thoughtful spacing. A quieter palette. A clearer view of the business, shaped around its own identity and imagery.</p></div>${designPoints()}</div></section>`;
}

function conceptSection(b: PreparedBusiness, template: DemoTemplate): string {
  const modifier = template.id === "momentum" ? " momentum-concept" : template.id === "folio" ? " folio-concept" : template.id === "clarity" ? " clarity-concept" : "";
  const website = b.website ? `<a class="official-link" href="${e(b.website)}" target="_blank" rel="noopener noreferrer">Visit the business’s existing website ${arrow}</a>` : "";
  return `<section id="concept" class="concept-section${modifier}"><div class="section-heading"><div><div class="eyebrow">A conversation starter, by ${e(b.studioName)}</div><h2>What if this was<br>your next first impression?</h2></div>${template.id === "folio" ? `<span class="folio-small-art" aria-hidden="true">${mark}</span>` : ""}</div><p>This is an independent website concept created by ${e(b.studioName)} for review. It is not ${e(b.businessName)}’s official website, and no partnership or endorsement is implied. It does not accept enquiries, bookings or payments. Business copy, services and contact details need owner confirmation before launch.</p><dl class="facts"><div><dt>Business</dt><dd>${e(b.businessName)}</dd></div><div><dt>Research location supplied</dt><dd>${e(b.location)}</dd></div>${b.address ? `<div><dt>Street address / business website</dt><dd>${e(b.address)}</dd></div>` : ""}${b.contactEmail ? `<div><dt>Email supplied / display only</dt><dd>${e(b.contactEmail)}</dd></div>` : ""}${b.phone ? `<div><dt>Phone supplied / display only</dt><dd>${e(b.phone)}</dd></div>` : ""}<div><dt>Design direction</dt><dd>${e(template.name)} / Original ${e(b.studioName)} implementation</dd></div></dl>${website}${assetProvenance(b)}</section>`;
}

/** Pure, deterministic rendering: no network, random identifiers, timestamps, model calls or side effects. */
export function renderDemoWebsite(input: DemoBusinessInput): Readonly<RenderedDemoWebsite> {
  const b = prepare(input);
  const template = input.templateId === undefined ? selectDemoTemplate(b.industry) : getDemoTemplate(input.templateId);
  if (template.id === "immersive") {
    const rendered = renderImmersiveConcept(b);
    const styleHash = createHash("sha256").update(rendered.css).digest("base64");
    const policy = `default-src 'none'; script-src 'none'; style-src 'sha256-${styleHash}'; img-src data:; font-src 'none'; connect-src 'none'; media-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'`;
    const html = `<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="${e(policy)}"><meta name="description" content="${e(`Independent website concept for ${b.businessName} by ${b.studioName}. Not the business's official website.`)}"><title>${e(b.businessName)} — Independent Website Concept | ${e(b.studioName)}</title><style>${rendered.css}</style></head><body class="theme-immersive">${rendered.body}</body></html>`;
    return Object.freeze({ html, templateId: template.id, templateName: template.name, template, attribution: template.attribution,
      contentHash: createHash("sha256").update(html).digest("hex"), contentSecurityPolicy: `${policy}; frame-ancestors 'self'`, fixture: b.fixture,
      externalAssets: Object.freeze([] as string[]), designBrief: rendered.designBrief });
  }
  const css = baseCss + (template.id === "fieldwork" ? fieldworkCss : template.id === "momentum" ? momentumCss : template.id === "folio" ? folioCss : "") + businessAssetCss + (template.id === "clarity" ? clarityCss : "");
  const styleHash = createHash("sha256").update(css).digest("base64");
  const policy = `default-src 'none'; script-src 'none'; style-src 'sha256-${styleHash}'; img-src data:; font-src 'none'; connect-src 'none'; media-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'`;
  const content = template.id === "fieldwork" ? fieldwork(b) : template.id === "momentum" ? momentum(b) : template.id === "clarity" ? clarity(b) : folio(b);
  // Full-width direction bands escape the content wrapper using a single well-formed boundary.
  const split = content.split('<section id="direction"');
  const heroAndServices = split[0]!;
  const directionBand = split[1] ? `<section id="direction"${split[1]}` : "";
  const html = `<!doctype html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="${e(policy)}"><meta name="description" content="${e(`Independent website concept for ${b.businessName} by ${b.studioName}. Not the business's official website.`)}"><title>${e(b.businessName)} — Independent Website Concept | ${e(b.studioName)}</title><style>${css}</style></head><body class="theme-${template.id}"><a class="skip" href="#main">Skip to concept</a><div class="concept-notice"><span aria-hidden="true"></span><strong>Independent website concept by ${e(b.studioName)} • Not the business's official website</strong></div>${b.fixture ? '<div class="concept-fixture">FICTIONAL TEST RECORD — This business and its details are test data.</div>' : ""}<div class="wrap">${nav(b)}</div><main id="main"><div class="wrap">${heroAndServices}</div>${directionBand}<div class="wrap">${conceptSection(b, template)}</div></main><div class="wrap"><footer class="site-footer"><div class="mini-brand">${mark}<span>${e(b.studioName.toLocaleUpperCase("en-AU"))}<br>INDEPENDENT DESIGN CONCEPT${b.studioWebsite ? `<br><a href="${e(b.studioWebsite)}" target="_blank" rel="noopener noreferrer">${e(new URL(b.studioWebsite).hostname)}</a>` : ""}</span></div><div class="footer-license">Original design and implementation by ${e(b.studioName)}.<br>${template.visualReference ? `Visual reference: <a href="${e(template.visualReference.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e(template.visualReference.name)}</a>. No Apple code, assets or affiliation.<br>` : ""}Free-template inspiration: <a href="${e(template.inspiration.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e(template.inspiration.name)}</a> (<a href="${e(template.inspiration.licenceUrl)}" target="_blank" rel="noopener noreferrer">${e(template.inspiration.licence)}</a>). No upstream template code or assets embedded.<br>${b.images.length || b.logo ? "Business branding and photography: see source credits above. Usage rights require confirmation." : "Original illustration."} Service descriptions and business claims require confirmation.</div></footer></div></body></html>`;
  return Object.freeze({ html, templateId: template.id, templateName: template.name, template, attribution: template.attribution,
    contentHash: createHash("sha256").update(html).digest("hex"), contentSecurityPolicy: `${policy}; frame-ancestors 'self'`, fixture: b.fixture,
    externalAssets: Object.freeze([] as string[]) });
}

/** Convert only our fixed illustration markup into JSX. Untrusted business text never passes here. */
function illustrationJsx(svg: string): string {
  return svg.replace(/\bclass=/g, "className=").replace(/\bstroke-width=/g, "strokeWidth=")
    .replace(/\bstroke-linecap=/g, "strokeLinecap=").replace(/\bstroke-opacity=/g, "strokeOpacity=")
    .replace(/\bfill-opacity=/g, "fillOpacity=");
}

/**
 * A genuinely editable React/Vite project, generated locally from validated facts and our own code.
 * This is not Lovable output, a Lovable build, or a promise that a hosted Lovable project can import a ZIP.
 * The protected HTML preview remains a separate script-free artefact.
 */
export function exportDemoReactProject(input: DemoBusinessInput): Readonly<Record<string, string>> {
  if (input.templateId === "immersive") return exportImmersiveReactProject(prepare(input));
  if (input.templateId !== undefined && input.templateId !== "clarity") throw new Error("Build a Clarity concept before downloading its matching React source.");
  const b = prepare({ ...input, templateId: "clarity" });
  const template = getDemoTemplate("clarity");
  // JSON escapes every quote and control character. It is JavaScript data, never inserted into markup.
  const data = JSON.stringify(b, null, 2).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
  const app = `import type { ReactNode } from "react";

type BusinessImage = { dataUrl: string; sourceUrl: string; alt: string; mime: string; sha256: string; width: number; height: number };
type Concept = {
  businessName: string; location: string; industry: string; services: string[]; website: string | null;
  contactEmail: string | null; phone: string | null; description: string; fixture: boolean; address: string;
  profileSource: string | null; profileDetail: string; logo: BusinessImage | null; images: BusinessImage[];
  studioName: string; studioWebsite: string | null;
};
const data: Concept = ${data};
const Arrow = () => (${illustrationJsx(arrow)});
const Mark = () => (${illustrationJsx(mark)});
const OriginalArt = () => (${illustrationJsx(clarityArt())});
` + String.raw`
const SourceLink = ({ href, children }: { href: string; children: ReactNode }) => <a href={href} target="_blank" rel="noopener noreferrer">{children}</a>;
const Photo = ({ image, className, lazy = false, alt }: { image: BusinessImage; className: string; lazy?: boolean; alt?: string }) => <img className={className} src={image.dataUrl} width={image.width} height={image.height} alt={alt ?? image.alt} decoding="async" loading={lazy ? "lazy" : "eager"} />;

function Navigation() {
  return <div className="wrap"><header className="site-nav"><a className="brand" href="#main" aria-label={data.businessName + " concept home"}>{data.logo ? <span className="business-logo-frame"><Photo image={data.logo} className="business-logo" alt={data.businessName + " logo from its existing website"} /></span> : <Mark />}<span className="brand-name">{data.businessName}</span></a><nav className="nav-links" aria-label="Concept navigation"><a href="#services">Services</a><a href="#direction">The direction</a></nav><div className="nav-end"><a className="nav-button" href="#concept">About this concept <Arrow /></a></div></header></div>;
}

function Hero() {
  return <section className="hero clarity-hero"><div className="hero-text clarity-arrive"><div className="eyebrow">{data.industry} · {data.location}</div><h1>{data.businessName}<span>A fresh perspective.</span></h1><div className="hero-copy"><p>{data.description || "An independent website concept for " + data.businessName + ", exploring a clearer presentation of its business in " + data.location + "."}</p></div><a className="cta" href="#services">Explore the concept <Arrow /></a>{(data.address || data.phone) && <div className="business-location-line"><svg width="14" height="18" viewBox="0 0 14 18" fill="none" aria-hidden="true"><path d="M12 6.5C12 11 7 16 7 16S2 11 2 6.5a5 5 0 1 1 10 0Z" stroke="currentColor" /><circle cx="7" cy="6.5" r="1.5" stroke="currentColor" /></svg><span>{data.address || data.location}{data.phone && <><br />{data.phone} · display only</>}</span></div>}</div><div className={"clarity-visual" + (data.images.length ? " has-business-image" : "")}>{data.images[0] ? <Photo image={data.images[0]} className="business-hero-image" /> : <OriginalArt />}<div className="clarity-image-label"><strong>{data.businessName}</strong><span>{data.images.length ? "From the business’s own website" : "Original abstract illustration"}</span></div></div><div className="clarity-caption"><span>{data.images[0] ? <SourceLink href={data.images[0].sourceUrl}>Image from the business’s existing website</SourceLink> : "Original illustration / " + data.studioName}</span><span>Independent concept · Business details to be confirmed</span></div></section>;
}

function Services() {
  return <section id="services" className="service-section clarity-services"><div className="section-heading"><div><div className="eyebrow">The essentials, thoughtfully presented.</div><h2>Good work.<br />A clearer introduction.</h2></div><p>{data.services.length ? "Service names from the recorded research. Descriptions and business claims need confirmation before launch." : "A focused framework, ready for the business’s confirmed services and details."}</p></div>{data.services.length ? <div className="service-list">{data.services.map((service, index) => <div className="service-row" key={service}><span>{String(index + 1).padStart(2, "0")}</span><h3>{service}</h3><Arrow /></div>)}</div> : <p className="services-pending">Service information has not been verified for this concept. This space is reserved for confirmed details.</p>}</section>;
}

function Gallery() {
  if (data.images.length < 2) return null;
  return <section className="business-gallery" aria-label="Images from the business website"><div className="eyebrow">A closer look / From the business’s existing website</div><div className="business-gallery-grid">{data.images.slice(1).map((image, index) => <figure key={image.sha256 + index}><Photo image={image} className="business-gallery-image" lazy /><figcaption><span>{image.alt}</span><SourceLink href={image.sourceUrl}>Source {String(index + 2).padStart(2, "0")} ↗</SourceLink></figcaption></figure>)}</div></section>;
}

function Direction() {
  const points = [
    ["A stronger first impression.", "A distinct visual direction, shaped around the business rather than a generic landing page."],
    ["The useful details, up front.", "Space for verified services, location and contact details, with a clearer path through the page."],
    ["Made to feel right on mobile.", "A responsive design study that keeps the essential information easy to read on smaller screens."],
  ];
  return <section id="direction" className="design-section clarity-direction"><div className="wrap design-grid"><div><div className="eyebrow">The creative direction</div><h2>More room<br />for what<br /><span>matters.</span></h2><p className="clarity-direction-copy">Thoughtful spacing. A quieter palette. A clearer view of the business, shaped around its own identity and imagery.</p></div><div>{points.map(([heading, copy], index) => <div className="design-point" key={heading}><span>{String(index + 1).padStart(2, "0")}</span><div><h3>{heading}</h3><p>{copy}</p></div></div>)}</div></div></section>;
}

function Provenance() {
  const sources = [...(data.logo ? [{ label: "Business logo", image: data.logo }] : []), ...data.images.map((image, index) => ({ label: "Business image " + (index + 1), image }))];
  if (!data.profileSource && !sources.length) return <p className="asset-fallback-note">Business logos and photographs have not been verified for this concept. The illustration is original {data.studioName} artwork.</p>;
  return <div className="asset-provenance"><p>{sources.length ? "Business branding and photographs are sourced from the business’s existing website for this independent design review. Their inclusion does not establish ownership, permission or endorsement; usage rights and business details need confirmation before launch." : "The business’s existing website was checked, but no suitable business logo or photograph was available for this concept. The illustration is original " + data.studioName + " artwork."}</p>{data.profileSource && <p><SourceLink href={data.profileSource}>Business information source ↗</SourceLink>{data.address ? " · Street address shown as published by the business; not independently verified." : " · Street address not confirmed; the supplied research location is shown."}</p>}{sources.length > 0 && <ul className="image-source-list">{sources.map(({ label, image }) => <li key={label}><SourceLink href={image.sourceUrl}>{label} ↗</SourceLink></li>)}</ul>}</div>;
}

function AboutConcept() {
  return <section id="concept" className="concept-section clarity-concept"><div className="section-heading"><div><div className="eyebrow">A conversation starter, by {data.studioName}</div><h2>What if this was<br />your next first impression?</h2></div></div><p>This is an independent website concept created by {data.studioName} for review. It is not {data.businessName}’s official website, and no partnership or endorsement is implied. It does not accept enquiries, bookings or payments. Business copy, services and contact details need owner confirmation before launch.</p><dl className="facts"><div><dt>Business</dt><dd>{data.businessName}</dd></div><div><dt>Research location supplied</dt><dd>{data.location}</dd></div>{data.address && <div><dt>Street address / business website</dt><dd>{data.address}</dd></div>}{data.contactEmail && <div><dt>Email supplied / display only</dt><dd>{data.contactEmail}</dd></div>}{data.phone && <div><dt>Phone supplied / display only</dt><dd>{data.phone}</dd></div>}<div><dt>Design direction</dt><dd>Clarity / Original {data.studioName} implementation</dd></div></dl>{data.website && <a className="official-link" href={data.website} target="_blank" rel="noopener noreferrer">Visit the business’s existing website <Arrow /></a>}<Provenance /></section>;
}

function Footer() {
  return <div className="wrap"><footer className="site-footer"><div className="mini-brand"><Mark /><span>{data.studioName.toLocaleUpperCase("en-AU")}<br />INDEPENDENT DESIGN CONCEPT{data.studioWebsite && <><br /><SourceLink href={data.studioWebsite}>{new URL(data.studioWebsite).hostname}</SourceLink></>}</span></div><div className="footer-license">Original design and implementation by {data.studioName}.<br />Visual reference: <SourceLink href="https://www.apple.com/">Apple</SourceLink>. No Apple code, assets or affiliation.<br />Free-template inspiration: <SourceLink href="https://github.com/themesberg/landwind">Landwind</SourceLink> (<SourceLink href="https://github.com/themesberg/landwind/blob/main/LICENSE">MIT</SourceLink>). No upstream template code or assets embedded.<br />{data.images.length || data.logo ? "Business branding and photography: see source credits above. Usage rights require confirmation." : "Original illustration."} Service descriptions and business claims require confirmation.</div></footer></div>;
}

export default function App() {
  return <><a className="skip" href="#main">Skip to concept</a><div className="concept-notice"><span aria-hidden="true" /><strong>Independent website concept by {data.studioName} • Not the business's official website</strong></div>{data.fixture && <div className="concept-fixture">FICTIONAL TEST RECORD — This business and its details are test data.</div>}<Navigation /><main id="main"><div className="wrap"><Hero /><Services /><Gallery /></div><Direction /><div className="wrap"><AboutConcept /></div></main><Footer /></>;
}
`;
  const title = `${b.businessName} — Independent Website Concept | ${b.studioName}`;
  const files = {
    "package.json": JSON.stringify({ name: "wulff-digital-private-concept", version: "1.0.0", private: true, type: "module", scripts: { dev: "vite --host 127.0.0.1", build: "tsc --noEmit && vite build", preview: "vite preview --host 127.0.0.1" }, dependencies: { react: "18.3.1", "react-dom": "18.3.1" }, devDependencies: { "@types/react": "^18.3.12", "@types/react-dom": "^18.3.1", "@vitejs/plugin-react": "^4.3.4", typescript: "^5.7.0", vite: "^5.4.11" } }, null, 2) + "\n",
    "index.html": `<!doctype html>\n<html lang="en-AU"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><title>${e(title)}</title></head><body class="theme-clarity"><div id="root"></div><script type="module" src="/src/main.tsx"></script></body></html>\n`,
    "vite.config.ts": 'import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\nexport default defineConfig({ plugins: [react()], base: "./" });\n',
    "tsconfig.json": JSON.stringify({ compilerOptions: { target: "ES2020", lib: ["ES2020", "DOM", "DOM.Iterable"], module: "ESNext", moduleResolution: "Bundler", jsx: "react-jsx", strict: true, skipLibCheck: true, resolveJsonModule: true, isolatedModules: true, esModuleInterop: true, allowSyntheticDefaultImports: true, noEmit: true }, include: ["src", "vite.config.ts"] }, null, 2) + "\n",
    "src/main.tsx": 'import React from "react";\nimport ReactDOM from "react-dom/client";\nimport App from "./App";\nimport "./index.css";\nReactDOM.createRoot(document.getElementById("root")!).render(<React.StrictMode><App /></React.StrictMode>);\n',
    "src/App.tsx": app,
    "src/index.css": baseCss + businessAssetCss + clarityCss,
    "README.md": `# Private Clarity website concept\n\nOriginal React, TypeScript and Vite source created locally for the studio identity selected in Jarvis. The business name, studio name and company website are stored as structured data in \`src/App.tsx\`.\n\n## Run on your laptop\n\nUse Node.js 22 or later. Run \`npm install\`, then \`npm run dev\`; the development server binds to your own machine. Run \`npm run build\` for a static production build. Dependency downloads require internet access but no Lovable build or voice API is called.\n\n## What this is\n\nThis is editable React/Vite code, not an iframe wrapper, Lovable-generated output or a full-stack Lovable project export. Its familiar React components can be adapted in your chosen code workflow; ZIP import into a hosted Lovable project is not promised. No Lovable account, credits, API key, model calls or paid voice service is used by this project. It contains no forms, payments, bookings, analytics or email-sending code.\n\nThe visual direction is inspired by Apple's restraint, spacing and product presentation. No Apple code, fonts, logos, imagery or other assets were copied, and no Apple affiliation is implied. ${template.attribution}\n\n## Business facts and assets\n\nThe structured \`data\` object in \`src/App.tsx\` contains the same validated business facts and embedded raster images used for this concept. React renders text as text. Images are embedded data URLs and do not load third-party trackers. Image sources and factual provenance are included in the page. Unavailable facts stay unfilled; original abstract artwork is used if no suitable photograph was available. ${b.fixture ? "THIS IS A FICTIONAL TEST RECORD. " : ""}This is an independent design proposal, not the business's official website. Confirm all details and asset usage rights before public launch.\n\n## Privacy\n\nThe download includes researched business information and private concept artwork. Keep it private until reviewed. Publishing, sending email or connecting a domain is a separate owner decision. The script-free hosted preview has its own restrictive content-security policy; this editable development project intentionally runs React and has no claim to share that preview's CSP.\n`,
  };
  return Object.freeze(files);
}
